        }

        double taxa = 0.0199;
        BigDecimal parcela = total.multiply(BigDecimal.valueOf(taxa))
            .divide(BigDecimal.ONE.subtract(BigDecimal.valueOf(Math.pow(1 + taxa, -parcelas))), 10, RoundingMode.HALF_EVEN);
        parcela = arredondar(parcela);

        BigDecimal totalFinal = parcela.multiply(BigDecimal.valueOf(parcelas));
        return totalFinal.subtract(total);
