            .divide(BigDecimal.ONE.subtract(BigDecimal.valueOf(Math.pow(1 + taxa, -parcelas))), 10, RoundingMode.HALF_EVEN);
        return arredondar(parcela);
    }

    return arredondar(totalFinal.divide(BigDecimal.valueOf(parcelas), 10, RoundingMode.HALF_EVEN));
}

